  currentBuilds: 0,
  resetDate: null
};

// Create quota data file path here
const quotaDataFile = path.join(__dirname, 'quota-data.json');

// Define loadQuotaData function here
function loadQuotaData() {
  if (fs.existsSync(quotaDataFile)) {
    const data = fs.readFileSync(quotaDataFile, 'utf8');
    Object.assign(usageTracker, JSON.parse(data));
  }
}

